public static void apply(Matrix m, Unit unit, UEdge edge) {
    if (edge.mEnd.mStretchable) {
        float fBoneRestLength = unit.getScene().boneRestLength(SceneHelper.removeNumber(unit.getName()), edge.mEnd.getId());
        if (fBoneRestLength <= 0.0f) {
            return;
        }
        float scale = fBoneRestLength * unit.getScale();
        if (scale <= 0.0f) {
            return;
        }
        float length = (float) (edge.getLength() / ((double) scale));
        if (length == 1.0f) {
            return;
        }
        float angle = edge.getAngle();
        float f = edge.mStart.x;
        float f2 = edge.mStart.y;
        m.postRotate(-angle, f, f2);
        m.postScale(length, 1.0f, f, f2);
        m.postRotate(angle, f, f2);
    }
}
